mapper.select:
SELECT  FROM train_server_account
WHERE server_id = #{serverId} AND owner_user_id = #{ownerUserId}
ORDER BY account_id

SELECT  FROM train_server_account
WHERE enabled = 1 AND has_credential = 1 AND account_id > #{afterAccountId}
    AND server_id IN (SELECT server_id FROM train_server WHERE enabled = 1)
ORDER BY account_id LIMIT #{limit}

mapper.update:
UPDATE train_server_account
SET credential_ciphertext = #{credentialCiphertext}, passphrase_ciphertext = #{passphraseCiphertext},
    updated_at = #{updatedAt}
WHERE account_id = #{authorizedAccountId}

UPDATE train_server_account
SET last_probe_at = #{sampledAt}, status = #{status}, error_code = #{errorCode},
    last_success_at = CASE WHEN #{successful} THEN #{sampledAt} ELSE last_success_at END,
    updated_at = #{sampledAt}
WHERE account_id = #{accountId}
